head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > dragEndFunction]<br/>Drag 된 데이터가 GridView 에 Drop 되었을때 호출할 사용자 정의 함수를 설정합니다.",
    "validation" : [
        "DrillDown 이 적용된 서로 다른 GridView 에 데이터가 Drop 되었을때 dragEndFunction 사용자 함수가 호출되며 파라미터로 targetRowIndex, rowXml, info 가 전달됩니다.",
        "선택 상태와 관계없이 Drag 가 시작된 Row 와 자식 Row 의 데이터가 전달됩니다.",
        "targetRowIndex : 데이터가 Drop 된 위치의 Row 인덱스값이 전달됩니다.",
        "rowXml : Drag 가 시작된 Row 의 전체 데이터가 XML 객체로 전달됩니다.",
        "info.fromRowIndex : Drag 가 시작된 Row 의 인덱스값을 갖습니다.",
        "info.fromGridViewId : Drag 가 시작된 GridView 의 렌더링 ID 값을 갖습니다.",
        "info.toRowIndex : 데이터가 Drop 된 위치의 Row 인덱스값을 갖습니다.",
        "info.toGridViewId : 데이터가 Drop 된 GridView 의 렌더링 ID 값을 갖습니다.",
        "info.removedData : Drag 가 시작된 Row 와 자식 Row 의 데이터를 배열로 갖습니다.",
        "info.removedRowIndex : Drag 가 시작된 Row 와 자식 Row 의 인덱스값을 배열로 갖습니다.",
        "info.rowJSON : Drag 가 시작된 Row 와 자식 Row 의 데이터를 JSON 객체 배열로 갖습니다.",
        "사용자 함수에서 명시적으로 true 를 반환하는 경우 Drag 가 시작된 Row 와 자식 Row 의 원본 데이터가 dataDragDropCell 속성값에 관계없이 Row 단위로 삭제됩니다.",
        "데이터가 Drop 되는 GridView 에 dragEndFunction 사용자 함수가 정의된 경우 Drop 되는 GridView 도 DrillDown 이 적용되고 Drag 가 허용되어야 dragEndFunction 사용자 함수가 호출되며, DrillDown 이 적용되지 않았거나 Drag 가 허용되어 있지 않으면 호출되지 않습니다.",
        "dragEndFunction 은 dragStartFunction 실행 후 실행되며, 실행 시 ondatadrop 이벤트는 발생하지 않습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // con 초기값 보관 (Drop 대상 target2 의 DrillDown/Drag 허용 토글)
    //  - cTargetDrillDown : target2 에 DrillDown 적용 여부 (true=적용)
    //  - cTargetDragAllow : target2 의 setDrillDownDragDrop 허용 여부 (true=허용)
    scwin.gVar = { "cTargetDrillDown": "true", "cTargetDragAllow": "true" };

    // con selectbox 기본값 명시 (bound gdl_boolean 은 초기 selectedIndex 미적용 → setValue)
    con_targetDrillDown.setValue("true");
    con_targetDragAllow.setValue("true");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 — 좌/우 모두 DrillDown(계층형) GridView
//  - 좌 target1(Drag 소스) : DrillDown + dataDragDrop=true + setDrillDownDragDrop(true)
//  - 우 target2(Drop 대상) : DrillDown(con 토글) + dataDragDrop=true + setDrillDownDragDrop(con 토글) + dragEndFunction 정의
//    -> 가이드 @spec : 서로 다른 DrillDown GridView 에 Drop 시 target2(Drop 대상)의 dragEndFunction 이
//       (targetRowIndex, rowXml, info) 로 호출됨. info 에 from/to 인덱스·GridViewId, removedData/removedRowIndex/rowJSON 포함.
//    -> @spec 조건 : Drop 대상도 DrillDown 적용 + Drag 허용(setDrillDownDragDrop true) 이어야 호출.
//       con 으로 미적용/미허용을 토글해 미호출(Drop 취소)도 검증.
scwin.comp_init = async function () {
    // con 현재값 반영 (Target 재생성 버튼이 comp_init 재호출)
    scwin.gVar.cTargetDrillDown = con_targetDrillDown.getValue();   // "true" / "false"
    scwin.gVar.cTargetDragAllow = con_targetDragAllow.getValue();   // "true" / "false"

    // 기존 target / dataList 있으면 삭제 (2개 그리드 + 2개 dataList)
    if (typeof dlt_bind1 !== 'undefined') { $p.data.remove("dlt_bind1"); }
    if (typeof dlt_bind2 !== 'undefined') { $p.data.remove("dlt_bind2"); }
    if (typeof target1 !== 'undefined') { target1.remove(); }
    if (typeof target2 !== 'undefined') { target2.remove(); }
    // 이전에 만든 flex wrapper 도 제거 (Target 재생성 시 중복 누적 방지)
    if (scwin.gridFlexWrap && scwin.gridFlexWrap.parentNode) {
        scwin.gridFlexWrap.parentNode.removeChild(scwin.gridFlexWrap);
    }

    // 안내 라벨 (가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 왼쪽 target1=Drag 소스(DrillDown+Drag 허용), 오른쪽 target2=Drop 대상.\n[절차] target1 의 부모/행을 target2 로 드래그하면 target2 의 dragEndFunction 이 (targetRowIndex, rowXml, info) 로 호출됩니다.\n[조건] target2 도 DrillDown 적용 + Drag 허용이어야 호출됩니다(con 토글로 미적용/미허용 시 미호출)."', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();

    // 좌우 배치용 flex wrapper 와 좌/우 셀(원시 DOM div) 생성
    let grpBasic = document.querySelector('.tc_group_basic');
    scwin.gridFlexWrap = document.createElement('div');
    scwin.gridFlexWrap.style.cssText = 'display:flex; gap:20px; align-items:flex-start;';
    let cellLeft = document.createElement('div');
    let cellRight = document.createElement('div');
    scwin.gridFlexWrap.appendChild(cellLeft);
    scwin.gridFlexWrap.appendChild(cellRight);
    grpBasic.appendChild(scwin.gridFlexWrap);

    // === 계층 DataList 2개 (본부 depth1 > 팀 depth2 > 사원 depth3) ===
    scwin._createDrillDataList("dlt_bind1", strNameSpace);
    scwin._createDrillDataList("dlt_bind2", strNameSpace);
    //  - 좌 target1 : 충분한 계층 데이터(7행), 우 target2 : 빈 상태로 시작(이동 가시화)
    $p.getComponentById("dlt_bind1").setJSON(scwin._getDrillJSON(), false);
    $p.getComponentById("dlt_bind2").setJSON(scwin._getDrillJSONRight(), false);

    // target1(좌, Drag 소스) : DrillDown 적용 + dataDragDrop=true
    scwin.target1 = await scwin._createDrillGrid("target1", "dlt_bind1", "좌(Drag 소스)", true, '', strNameSpace, cellLeft);

    // target2(우, Drop 대상) : DrillDown 은 con 토글 / dataDragDrop=true / dragEndFunction 정의
    let useDrillTarget2 = (scwin.gVar.cTargetDrillDown === "true");
    let extraAttr2 = ' dragEndFunction="scwin.target2_dragEndFunc"';
    scwin.target2 = await scwin._createDrillGrid("target2", "dlt_bind2", "우(Drop 대상)", useDrillTarget2, extraAttr2, strNameSpace, cellRight);

    // DrillDown Drag&Drop 활성화
    //  - target1(소스) : 항상 Drag 허용
    //  - target2(Drop 대상) : con 토글로 허용/미허용 (DrillDown 미적용이면 setDrillDownDragDrop 무의미)
    target1.setDrillDownDragDrop(true);
    if (useDrillTarget2 && scwin.gVar.cTargetDragAllow === "true") {
        target2.setDrillDownDragDrop(true);
    }
};



// 계층(DrillDown) DataList 생성 헬퍼
scwin._createDrillDataList = function (dltId, strNameSpace) {
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="' + dltId + '" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
};

// 계층 데이터 (본부 depth1 > 팀 depth2 > 사원 depth3)
scwin._getDrillJSON = function () {
    return [
        { "name": "영업본부", "dept": "Sales", "depth": 1 },
        { "name": "영업1팀",  "dept": "Sales", "depth": 2 },
        { "name": "김영업",   "dept": "Sales", "depth": 3 },
        { "name": "이영업",   "dept": "Sales", "depth": 3 },
        { "name": "개발본부", "dept": "Dev",   "depth": 1 },
        { "name": "개발1팀",  "dept": "Dev",   "depth": 2 },
        { "name": "박개발",   "dept": "Dev",   "depth": 3 }
    ];
};

// 우측(target2) 초기 데이터 — Drop 위치(Row)를 잡을 수 있도록 시드 계층 1세트 유지
//  (완전 빈 그리드는 Drop 대상 Row(td)가 없어 Drop 위치 인덱스를 특정하기 어려움)
scwin._getDrillJSONRight = function () {
    return [
        { "name": "관리본부", "dept": "Admin", "depth": 1 },
        { "name": "총무팀",   "dept": "Admin", "depth": 2 }
    ];
};



// 계층(DrillDown) GridView 생성 헬퍼
//  - useDrill=true : name 컬럼 inputType="drilldown" (DrillDown 적용)
//  - useDrill=false : name 컬럼 inputType="text" (DrillDown 미적용 — 미호출 검증용)
//  - depth 를 화면 바인딩 컬럼으로 노출 → 자동이동/계층 복원이 정상(미바인딩 depth 누락 결함 우회)
scwin._createDrillGrid = async function (gid, dltId, captionText, useDrill, extraAttr, strNameSpace, cParent) {
    let properties = { dataList: "data:" + dltId, dataDragDrop: "true" };
    let cList = $c.gcm.createCList(properties);

    let nameCol = useDrill
        ? '<w2:column width="200" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>'
        : '<w2:column width="200" style="" inputType="text" id="name" dataList="name"></w2:column>';

    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + extraAttr + ' id="" style="width:340px;height:280px;">';
    strTarget += '<w2:caption style="" id="" value="' + captionText + '"></w2:caption>';
    strTarget += '<w2:header style="" id="">';
    strTarget += '<w2:row style="" id="">';
    strTarget += '<w2:column width="200" style="" inputType="text" id="" value="이름(DrillDown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="" value="부서"></w2:column>';
    strTarget += '<w2:column width="60" style="" inputType="text" id="" value="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="">';
    strTarget += '<w2:row style="" id="">';
    strTarget += nameCol;
    strTarget += '<w2:column width="*" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="60" style="" inputType="text" id="depth" dataList="depth"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    let grp_comp = cParent;   // 좌/우 셀(원시 DOM div) 그대로 parent 로 사용
    return await $p.dynamicCreate(gid, "gridView", strTarget, grp_comp);
};



// dragEndFunction : 데이터가 Drop 된 GridView(target2=우)에 정의된 사용자 정의 함수 (검증 대상)
//  - DrillDown 서로 다른 GridView @spec : (targetRowIndex, rowXml, info) 전달
//      targetRowIndex : Drop 위치 Row 인덱스
//      rowXml         : Drag 시작 Row 의 전체 데이터 XML 객체
//      info.fromRowIndex / info.fromGridViewId / info.toRowIndex / info.toGridViewId
//      info.removedData    : Drag 시작 Row 와 자식 Row 데이터 배열
//      info.removedRowIndex : Drag 시작 Row 와 자식 Row 인덱스 배열
//      info.rowJSON        : Drag 시작 Row 와 자식 Row 데이터 JSON 객체 배열
//  - this : Drag 가 시작된 GridView(소스 target1) — 엔진이 call(_this=소스,...) 로 호출.
//  - 명시적으로 true 반환 시 Drag 시작 Row 와 자식 Row 원본이 dataDragDropCell 무관하게 Row 단위 삭제됨(소스 측).
//  - 대상(target2) 삽입은 엔진이 수행하지 않으므로 본 핸들러에서 info.rowJSON 으로 직접 복원(depth 포함).
scwin.target2_dragEndFunc = function (targetRowIndex, rowXml, info) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // rowXml 의 XML 객체 여부 및 name 값 추출 (전체 데이터 XML 객체 확인용)
    var isXmlObj = !!(rowXml && rowXml.nodeType && rowXml.nodeName);
    var rowXmlName = "";
    if (isXmlObj) {
        var nameNode = rowXml.querySelector ? rowXml.querySelector("name") : null;
        if (nameNode) { rowXmlName = nameNode.textContent; }
    }

    bottom.setReturnValue("▶ dragEndFunction 호출 (Drop 대상 target2 에 정의된 함수가 호출됨)");
    bottom.setReturnValue("targetRowIndex : " + targetRowIndex);
    bottom.setReturnValue("rowXml : " + (isXmlObj ? "XML 객체 (name=" + rowXmlName + ")" : String(rowXml)));
    bottom.setReturnValue("info.fromRowIndex : " + info.fromRowIndex + " / info.fromGridViewId : " + info.fromGridViewId);
    bottom.setReturnValue("info.toRowIndex : " + info.toRowIndex + " / info.toGridViewId : " + info.toGridViewId);
    bottom.setReturnValue("info.removedData : " + JSON.stringify(info.removedData));
    bottom.setReturnValue("info.removedRowIndex : " + JSON.stringify(info.removedRowIndex));
    bottom.setReturnValue("info.rowJSON : " + JSON.stringify(info.rowJSON));

    // Drop 대상(target2)에 실제 행 삽입 (계층 depth 복원)
    //  - 서로 다른 DrillDown 그리드 분기에서 엔진은 소스 삭제만 수행하고 대상 삽입은 사용자 구현 영역.
    //  - [엔진 한계] target2.drilldown.appendNode(targetRowIndex, info.removedData) 사용 시 depth 가 null 로 들어감.
    //      appendNode 가 options.depthColumn(컬럼명 'depth')을 parseInt 로 인덱스화하다 NaN 이 되어
    //      depth 슬롯을 못 채움(값 뒤섞임/계층 깨짐). → 우회: info.rowJSON(name/dept/depth 정확)으로
    //      dataList 에 직접 insertRow + setCellData 하여 depth 까지 정확 복원.
    //  - drop 위치 행의 depth 에 맞춰 이동 서브트리 루트의 depth 를 재정렬(shift)해 계층 일관성 유지.
    var insertedCount = 0;
    try {
        var realIdx = target2.getRealRowIndex(targetRowIndex);   // 표시 인덱스 → dataList 실제 인덱스
        if (realIdx == null || realIdx < 0) { realIdx = dlt_bind2.getRowCount(); }
        var dropDepth = parseInt(target2.getCellData(targetRowIndex, "depth"), 10);
        var rowJSON = info.rowJSON || [];
        var rootDepth = rowJSON.length ? parseInt(rowJSON[0].depth, 10) : 1;
        var shift = (isNaN(dropDepth) ? 0 : dropDepth - rootDepth);   // 루트를 drop 행과 같은 depth 로
        for (var i = 0; i < rowJSON.length; i++) {
            var r = rowJSON[i];
            dlt_bind2.insertRow(realIdx + i, false);
            dlt_bind2.setCellData(realIdx + i, "name", r.name);
            dlt_bind2.setCellData(realIdx + i, "dept", r.dept);
            dlt_bind2.setCellData(realIdx + i, "depth", parseInt(r.depth, 10) + shift);
            insertedCount++;
        }
        target2.refresh();
    } catch (e) {}
    bottom.setReturnValue("[이동 결과] target2 에 행 " + insertedCount + "개 추가 (name/dept/depth 정확 복원, 총 행 수=" + target2.getRowCount() + ")");

    // true 반환 → 엔진이 Drag 시작 Row + 자식 Row 원본을 Row 단위로 삭제 (지연 삭제 후 실제 잔여 행 수 출력)
    var srcId = info.fromGridViewId;
    setTimeout(function () {
        var src = $p.getComponentById(srcId);
        if (src) { bottom.setReturnValue("[반환 true] 소스 target1 Drag 시작 Row 와 자식 Row 삭제 완료 (삭제 후 target1 총 행 수=" + src.getRowCount() + ")"); }
    }, 0);
    return true;
};
